// routes/onboarding.ts
async function onboardingRoutes(app2) {
  app2.post("/api/onboarding/organization", {
    schema: createOrganizationSchema,
    preHandler: [authenticate, requirePlatformRoot()]
  }, createOrganization);
  app2.post("/api/onboarding/draft", saveDraft);
  app2.get("/api/onboarding/draft", getDraft);
  const totpAccess = { preHandler: [authenticate], config: { rateLimit: { max: process.env.NODE_ENV === "test" ? 1e3 : 5, timeWindow: "1 minute" } } };
  app2.post("/api/onboarding/totp/setup", totpAccess, setupOnboardingTOTP);
  app2.post("/api/onboarding/totp/verify", totpAccess, verifyOnboardingTOTP);
  const platformRoot = { preHandler: [authenticate, requirePlatformRoot()] };
  const manageOrg = { preHandler: [authenticate, checkPermission("MANAGE_ORGANIZATION")] };
  app2.get("/api/organizations", manageOrg, getAllOrganizations);
  app2.get(
    "/api/onboarding/organizations/:id/members",
    { ...manageOrg, schema: organizationIdParamSchema },
    getOrganizationMembers
  );
  app2.get("/api/admin/users", { ...platformRoot, schema: globalUsersQuerySchema }, getGlobalUsers);
  app2.put("/api/admin/users/:id/status", { ...platformRoot, schema: {
    ...organizationIdParamSchema,
    body: { type: "object", required: ["isActive"], properties: { isActive: { type: "boolean" } }, additionalProperties: false }
  } }, updateGlobalUserStatus);
  app2.delete("/api/organizations/:id/members/:userId", { preHandler: [authenticate, checkPermission("MANAGE_STAFF")], schema: {
    params: { type: "object", required: ["id", "userId"], properties: { id: { type: "string", pattern: "^[a-fA-F0-9]{24}$" }, userId: { type: "string", pattern: "^[a-fA-F0-9]{24}$" } }, additionalProperties: false }
  } }, removeOrganizationMember);
  app2.patch("/api/organizations/:id/members/:userId/location-access", { ...manageOrg, schema: {
    params: {
      type: "object",
      required: ["id", "userId"],
      additionalProperties: false,
      properties: { id: { type: "string", pattern: "^[a-fA-F0-9]{24}$" }, userId: { type: "string", pattern: "^[a-fA-F0-9]{24}$" } }
    },
    body: {
      type: "object",
      required: ["mode", "locationIds", "expectedRevision"],
      additionalProperties: false,
      properties: {
        mode: { type: "string", enum: ["all", "selected"] },
        expectedRevision: { type: "integer", minimum: 0 },
        locationIds: { type: "array", maxItems: 100, uniqueItems: true, items: { type: "string", pattern: "^[a-fA-F0-9]{24}$" } }
      }
    }
  } }, updateMemberLocationAccess);
  app2.get("/api/admin/hierarchy", platformRoot, getPlatformHierarchy);
  app2.get("/api/admin/dashboard", { ...platformRoot, schema: {
    querystring: { type: "object", properties: { range: { type: "string", enum: ["7D", "30D", "90D"], default: "30D" } }, additionalProperties: false }
  } }, getPlatformDashboard);
  app2.put("/api/organizations/:id", { ...manageOrg, schema: updateOrganizationSchema }, updateOrganizationById);
  app2.delete("/api/organizations/:id", { ...platformRoot, schema: organizationIdParamSchema }, deleteOrganizationById);
  app2.get("/api/onboarding/organization/preferences", { preHandler: [authenticate] }, getOrganizationWorkflowPreferences);
  app2.get("/api/onboarding/organization/me", manageOrg, getOrganizationSettings);
  app2.put("/api/onboarding/organization/me", { ...manageOrg, schema: { body: updateOrganizationSchema.body } }, updateOrganizationSettings);
  app2.get("/api/onboarding/organization/me/smtp", manageOrg, getOrganizationSmtp);
  app2.put("/api/onboarding/organization/me/smtp", manageOrg, updateOrganizationSmtp);
}

