async function locationRoutes(app2) {
  const manageLocations = { preHandler: [authenticate, requireModule("locations"), checkPermission("MANAGE_LOCATIONS"), enforceSubscriptionActive] };
  const viewLocations = { preHandler: [authenticate, requireModule("locations"), checkPermission("VIEW_LOCATIONS")] };
  app2.post("/api/onboarding/locations", { ...manageLocations, schema: createLocationSchema }, createLocation);
  app2.get("/api/onboarding/locations", viewLocations, getLocations);
  app2.put("/api/onboarding/locations/:id", { ...manageLocations, schema: updateLocationSchema }, updateLocation);
  app2.put("/api/onboarding/locations/:id/publication", {
    preHandler: [authenticate, checkPermission("MANAGE_LOCATIONS")],
    schema: { params: updateLocationSchema.params, body: { type: "object", required: ["isPublished"], properties: { isPublished: { type: "boolean" } }, additionalProperties: false } }
  }, setLocationPublication);
  app2.delete("/api/onboarding/locations/:id", manageLocations, deleteLocation);
  app2.post("/api/onboarding/locations/:id/reactivate", manageLocations, reactivateLocation);
  app2.put("/api/onboarding/locations/:id/reactivate", manageLocations, reactivateLocation);
  app2.post("/api/departments", { ...manageLocations, schema: createDepartmentSchema }, createDepartment);
  app2.get("/api/departments", viewLocations, getDepartments);
  app2.post("/api/onboarding/doctors/assignments", { ...manageLocations, schema: assignDoctorSchema }, assignDoctor);
  app2.get("/api/onboarding/doctors/assignments", viewLocations, getDoctorAssignments);
  app2.put("/api/onboarding/doctors/assignments/:id", manageLocations, updateAssignment);
  app2.delete("/api/onboarding/doctors/assignments/:id", manageLocations, removeAssignment);
}

