async function accessContext(req) {
  const { id: id5 } = req.params;
  const scope2 = resolveAuthorizedOrganizationScope(req);
  if (!scope2.allowed || !scope2.organizationId || !req.user?.sessionId || ["guest", "patient", "family_member"].includes(req.user.role)) return null;
  if (!/^[a-f\d]{24}$/i.test(id5)) return null;
  const patient = await getOrganizationPatient(id5, scope2.organizationId);
  if (!patient) return null;
  const account = patient.userId;
  const target = account?.phone || patient.phone ? { phone: account?.phone || patient.phone } : { email: account?.email || patient.email };
  if (!target.phone && !target.email) throw new Error("Patient has no contact number or email. Update their contact details first.");
  return {
    patientId: id5,
    organizationId: scope2.organizationId,
    userId: req.user.id,
    sessionId: req.user.sessionId,
    target,
    context: `${id5}:${scope2.organizationId}:${req.user.id}:${req.user.sessionId}`
  };
}
