async function clinicalRoutes(app2) {
  const viewEhr = {
    preHandler: [
      authenticate,
      requireModule("consultations"),
      checkAnyPermissionOrRoles(["patient", "family_member"], "VIEW_EHR")
    ]
  };
  const manageNotes = { preHandler: [authenticate, requireModule("consultations"), checkPermission("MANAGE_CLINICAL_NOTES")] };
  app2.get("/api/patients/:id/timeline", viewEhr, getPatientTimelineController);
  const recordAccess = { preHandler: [authenticate, requireModule("consultations"), checkPermission("VIEW_EHR")], config: { rateLimit: { max: process.env.NODE_ENV === "test" ? 1e3 : 5, timeWindow: "1 minute" } } };
  app2.post("/api/patients/:id/record-access/request", recordAccess, requestPatientRecordOtp);
  app2.post("/api/patients/:id/record-access/verify", recordAccess, verifyPatientRecordOtp);
  app2.post("/api/encounters", manageNotes, createEncounterController);
  app2.post("/api/clinical-notes", manageNotes, saveDraftClinicalNoteController);
  app2.put("/api/clinical-notes/:id/sign", manageNotes, signClinicalNoteController);
  app2.post("/api/clinical-notes/:id/amend", manageNotes, amendClinicalNoteController);
  app2.get("/api/patients/:id/clinical-notes/history", viewEhr, getClinicalNoteHistoryController);
  app2.post("/api/prescriptions/evaluate-safety", manageNotes, evaluatePrescriptionSafetyController);
  app2.post("/api/prescriptions/override-evaluation", manageNotes, overrideCDSEvaluationController);
  app2.get("/api/prescriptions/:id/verify-integrity", viewEhr, verifyPrescriptionIntegrityController);
  app2.post("/api/prescriptions/:id/amend", manageNotes, amendPrescriptionController);
  app2.post("/api/encounters/:id/evaluate-score", {
    preHandler: [authenticate, requireModule("consultations"), checkAnyPermission("EVALUATE_NEWS2", "MANAGE_EHR", "MANAGE_CLINICAL_NOTES")]
  }, evaluateEncounterScoreController);
  app2.get("/api/encounters/:id/scores", viewEhr, getEncounterScoresController);
  app2.post("/api/alerts/:id/acknowledge", manageNotes, acknowledgeAlertController);
  app2.get("/api/patients/:id/vital-trends", viewEhr, getPatientVitalTrendsController);
  const { getOpdTemplates: getOpdTemplates2, createOpdTemplate: createOpdTemplate2, deleteOpdTemplate: deleteOpdTemplate2 } = await Promise.resolve().then(() => (init_opdTemplate(), opdTemplate_exports));
  const viewTemplates = { preHandler: [authenticate, requireModule("consultations"), checkAnyPermission("VIEW_EHR", "MANAGE_EHR", "MANAGE_CLINICAL_NOTES")] };
  const manageTemplates = { preHandler: [authenticate, requireModule("consultations"), checkAnyPermission("MANAGE_EHR", "MANAGE_CLINICAL_NOTES")] };
  app2.get("/api/clinical/opd-templates", viewTemplates, getOpdTemplates2);
  app2.post("/api/clinical/opd-templates", manageTemplates, createOpdTemplate2);
  app2.delete("/api/clinical/opd-templates/:id", manageTemplates, deleteOpdTemplate2);
}

