// routes/laboratory.ts
async function laboratoryRoutes(app2) {
  const staffOnly = denyRoles("patient", "family_member", "guest");
  const viewLabCatalog = { preHandler: [authenticate, checkAnyPermission("VIEW_EHR", "MANAGE_ORDERS", "MANAGE_LAB_TESTS")] };
  const manageLabCatalog = { preHandler: [authenticate, staffOnly, checkPermission("MANAGE_LAB_TESTS")] };
  const viewOrders = { preHandler: [authenticate, checkAnyPermissionOrRoles(["patient", "family_member"], "VIEW_EHR", "MANAGE_ORDERS")] };
  const viewLabAnalytics = { preHandler: [authenticate, staffOnly, checkAnyPermission("VIEW_ANALYTICS", "MANAGE_ORDERS", "MANAGE_LAB_TESTS")] };
  const manageOrders = { preHandler: [authenticate, checkPermission("MANAGE_ORDERS")] };
  const viewEhr = { preHandler: [authenticate, checkPermission("VIEW_EHR")] };
  app2.get("/api/lab/patient/:patientId/comparison", { ...viewOrders, schema: patientLabComparisonSchema }, getPatientLabComparison);
  app2.get("/api/lab/tat-metrics", { ...viewLabAnalytics, schema: labTatMetricsSchema }, getLabTatMetrics);
  app2.post("/api/lab-tests", { ...manageLabCatalog, schema: createLabTestSchema }, createLabTest);
  app2.get("/api/lab-tests", { ...viewLabCatalog, schema: labTestsQuerySchema }, getLabTests);
  app2.put("/api/lab-tests/:id", { ...manageLabCatalog, schema: objectIdParamSchema }, updateLabTest);
  app2.delete("/api/lab-tests/:id", { ...manageLabCatalog, schema: objectIdParamSchema }, deleteLabTest);
  app2.post("/api/lab-orders", { ...manageOrders, schema: createLabOrderSchema }, createLabOrder);
  app2.get("/api/lab-orders", { ...viewOrders, schema: labOrdersQuerySchema }, getLabOrders);
  app2.put("/api/lab-orders/:id/sample", { ...manageOrders, schema: collectLabSampleSchema }, collectSample);
  app2.put("/api/lab-orders/:id/status", { ...manageOrders, schema: updateLabOrderStatusSchema }, updateLabOrderStatus);
  app2.put("/api/lab-orders/:id/result", { ...manageOrders, schema: uploadLabResultSchema }, uploadLabResult);
  app2.post("/api/encounters/:id/orders", manageOrders, placeOrderController);
  app2.get("/api/encounters/:id/orders", viewEhr, getEncounterOrdersController);
  app2.put("/api/orders/:id/collect", manageOrders, collectSampleOrderController);
  app2.put("/api/orders/:id/process", manageOrders, markProcessingController);
  app2.put("/api/orders/:id/result", manageOrders, recordResultController);
  app2.put("/api/orders/:id/cancel", manageOrders, cancelOrderController);
}

