async function predictNoShowRiskController(req, reply) {
  try {
    const { appointmentId, distanceKm } = req.body;
    if (!appointmentId || !mongoose180.Types.ObjectId.isValid(appointmentId)) {
      return reply.code(400).send(errorResponse("Valid appointmentId is required"));
    }
    const appointment = await Appointment.findById(appointmentId);
    if (!appointment) return reply.code(404).send(errorResponse("Appointment not found"));
    const locationAccess = await checkLocationAccess(req, appointment.locationId);
    if (!locationAccess.allowed) return reply.code(locationAccess.statusCode).send(errorResponse(locationAccess.message));
    const days2 = Math.max(0, Math.ceil((new Date(appointment.appointmentTime).getTime() - new Date(appointment.createdAt).getTime()) / 864e5));
    const noShows = await Appointment.countDocuments({
      patientId: appointment.patientId,
      status: "no-show",
      appointmentTime: { $lt: appointment.appointmentTime }
    });
    const patient = await Patient.findById(appointment.patientId).select("dob").lean();
    const age = patient?.dob ? Math.floor((Date.now() - new Date(patient.dob).getTime()) / (365.25 * 864e5)) : void 0;
    let riskScore = 15;
    if (days2 > 7) riskScore += 25;
    if (noShows > 0) riskScore += noShows * 20;
    if (distanceKm !== void 0 && distanceKm > 15) riskScore += 15;
    if (age !== void 0 && (age < 25 || age > 75)) riskScore += 10;
    const finalRiskPercent = Math.min(Math.max(riskScore, 5), 95);
    const riskCategory = finalRiskPercent > 60 ? "High" : finalRiskPercent > 30 ? "Medium" : "Low";
    return reply.code(200).send(
      successResponse({
        appointmentId,
        noShowRiskPercent: finalRiskPercent,
        riskCategory,
        recommendations: finalRiskPercent > 40 ? ["Send Automated SMS/WhatsApp Reminder 24h prior", "Offer Tele-consultation Alternative"] : ["Standard Booking Confirmation"]
      })
    );
  } catch (err) {
    console.error("predictNoShowRiskController error:", safeError(err));
    return reply.code(500).send(errorResponse("Internal server error"));
  }
}
async function auditBillingAnomaliesController(req, reply) {
  try {
    const { items, totalAmount } = req.body;
    if (!items || !Array.isArray(items)) {
      return reply.code(400).send(errorResponse("items array is required for billing audit"));
    }
    const anomalies = [];
    items.forEach((item) => {
      const desc = item.description.toLowerCase();
      if (desc.includes("consultation") && item.amount > 5e3) {
        anomalies.push(`Potential Upcoding Alert: High charge for ${item.description} (\u20B9${item.amount})`);
      }
      if (desc.includes("blood test") && items.some((i) => i.description.toLowerCase().includes("cbc"))) {
        anomalies.push(`Unbundled Code Alert: Duplicate lab charge component detected for ${item.description}`);
      }
    });
    return reply.code(200).send(
      successResponse({
        hasAnomalies: anomalies.length > 0,
        anomalyCount: anomalies.length,
        anomalies,
        auditedAmount: totalAmount
      })
    );
  } catch (err) {
    console.error("auditBillingAnomaliesController error:", safeError(err));
    return reply.code(500).send(errorResponse("Internal server error"));
  }
}
