var StreamingService = class {
  /**
   * Configures Fastify response headers for chunked Server-Sent Events (SSE) streaming.
   */
  static initSSEResponse(reply) {
    reply.raw.setHeader("Content-Type", "text/event-stream");
    reply.raw.setHeader("Cache-Control", "no-cache, no-transform");
    reply.raw.setHeader("Connection", "keep-alive");
    reply.raw.setHeader("X-Accel-Buffering", "no");
    reply.raw.statusCode = 200;
  }
  /**
   * Sends an SSE token chunk payload to the client.
   */
  static sendChunk(reply, chunk) {
    if (!reply.raw.writableEnded) {
      reply.raw.write(`data: ${JSON.stringify(chunk)}

`);
    }
  }
  /**
   * Finalizes and closes the SSE stream.
   */
  static endStream(reply, correlationId) {
    if (!reply.raw.writableEnded) {
      const finalChunk = {
        correlationId,
        chunkIndex: -1,
        text: "",
        isComplete: true
      };
      reply.raw.write(`data: ${JSON.stringify(finalChunk)}

`);
      reply.raw.end();
    }
  }
};

