  app2.get("/api/ai/health", getAIHealthController);
  app2.get("/api/ai/prompts", platformPrompts, listPromptTemplatesController);
  app2.post("/api/ai/prompts", platformPrompts, createPromptDraftController);
  app2.put("/api/ai/prompts/:id/approve", platformPrompts, approvePromptTemplateController);
  app2.post("/api/ai/prompts/test", platformPrompts, testPromptSandboxController);
  app2.post("/api/ai/tools/intent", clinicalAi, detectToolIntentController);
