async function imagingRoutes(app2) {
  const staffOnly = denyRoles("patient", "family_member", "guest");
  const viewImaging = { preHandler: [authenticate, staffOnly, checkAnyPermission("VIEW_EHR", "MANAGE_ORDERS")] };
  const manageImaging = { preHandler: [authenticate, staffOnly, checkPermission("MANAGE_ORDERS")] };
  const reportImaging = { preHandler: [authenticate, staffOnly, checkAnyPermission("MANAGE_CLINICAL_NOTES", "MANAGE_EHR")] };
  app2.post("/api/radiology/studies", { ...manageImaging, schema: createImagingStudySchema }, createImagingStudy);
  app2.get("/api/radiology/studies", { ...viewImaging, schema: imagingStudiesQuerySchema }, getImagingStudies);
  app2.get("/api/radiology/studies/:id/preview", viewImaging, imagingPreview);
  app2.put("/api/radiology/studies/:id/status", { ...manageImaging, schema: updateImagingStudyStatusSchema }, updateImagingStudyStatus);
  app2.put("/api/radiology/studies/:id/report", { ...reportImaging, schema: signRadiologyReportSchema }, signRadiologyReport);
}

