// routes/feedback.ts
async function feedbackRoutes(app2) {
  const auth = { preHandler: [authenticate] };
  const feedbackAnalytics = auth;
  app2.post("/api/feedback", { ...auth, schema: feedbackSubmissionSchema }, submitFeedback);
  app2.get("/api/feedback", { ...feedbackAnalytics, schema: feedbackQuerySchema }, getFeedback);
  app2.get("/api/feedback/stats", { ...feedbackAnalytics, schema: feedbackQuerySchema }, getFeedbackStats);
  app2.get("/api/feedback/eligible-visits", { ...auth, schema: feedbackQuerySchema }, getFeedbackEligibleVisits);
  app2.get("/api/feedback/mine", { ...auth, schema: feedbackQuerySchema }, getOwnFeedback);
  app2.get("/api/feedback/visit/:id", { ...auth, schema: { params: { type: "object", required: ["id"], properties: { id: { type: "string", pattern: "^[a-fA-F0-9]{24}$" } } } } }, getVisitFeedback);
}

