// routes/abdm.ts
async function abdmRoutes(app2) {
  const publicOtp = {
    config: { rateLimit: { max: process.env.NODE_ENV === "test" ? 1e3 : 5, timeWindow: "10 minutes" } }
  };
  const clinicalAccess = {
    preHandler: [
      authenticate,
      async (req, reply) => {
        if (["patient", "family_member", "guest"].includes(req.user?.role)) {
          return reply.code(403).send({ success: false, message: "Clinical staff access is required" });
        }
      },
      checkAnyPermission("VIEW_EHR", "MANAGE_EHR", "MANAGE_CLINICAL_NOTES")
    ]
  };
  app2.post("/api/abdm/generate-otp", publicOtp, generateAadhaarOtpController);
  app2.post("/api/abdm/generate-aadhaar-otp", publicOtp, generateAadhaarOtpController);
  app2.post("/api/abdm/verify-otp", publicOtp, verifyAadhaarOtpController);
  app2.post("/api/abdm/verify-aadhaar-otp", publicOtp, verifyAadhaarOtpController);
  app2.get("/api/abdm/search", clinicalAccess, searchAbhaController);
  app2.post("/api/abdm/search-abha", clinicalAccess, searchAbhaController);
  app2.post("/api/abdm/scan-share", clinicalAccess, scanAndShareCheckInController);
  app2.post("/api/abdm/scan-and-share", clinicalAccess, scanAndShareCheckInController);
  app2.get("/api/abdm/qr-standee/:locationId", clinicalAccess, getLocationQrStandeeController);
  app2.post("/api/abdm/care-contexts/link", clinicalAccess, linkCareContextController);
  app2.get("/api/abdm/care-contexts/:patientId", clinicalAccess, getPatientCareContextsController);
  app2.get("/api/abdm/fhir/encounter/:appointmentId", clinicalAccess, getFhirBundleController);
  app2.post("/api/abdm/hiu/consent-request", clinicalAccess, createConsentRequestController);
  app2.get("/api/abdm/hiu/consent-status/:consentRequestId", clinicalAccess, getConsentStatusController);
  app2.get("/api/abdm/hiu/health-data/:consentRequestId", clinicalAccess, getExternalHealthDataController);
}

