async function exportPatientData(patientId, organizationId, context2) {
  if (!organizationId || !context2?.actorId) throw new CommandError(403, "Organization and actual actor are required for export");
  const patient = await getOrganizationPatient(patientId, organizationId);
  if (!patient) throw new CommandError(404, "Patient not found in this organization");
  const resources = [
    ["appointments", Appointment, "_id appointmentTime appointmentType status locationId"],
    ["invoices", Invoice, "_id invoiceNumber status subtotal totalAmount amountPaid balanceDue createdAt locationId"],
    ...context2.includeClinical ? [
      ["encounters", Encounter, "_id encounterType status startedAt endedAt locationId"],
      ["prescriptions", Prescription, "_id medicineName dosage frequency duration instructions status createdAt locationId"],
      ["labOrders", LabOrder, "_id testId status clinicalReason result.value result.unit result.referenceRange result.interpretation result.isAbnormal result.notes createdAt locationId"]
    ] : []
  ];
  const records = {}, nextCursors = {};
  if (context2.resources && (context2.resources.length > 5 || context2.resources.some((name) => !resources.some(([key2]) => key2 === name)))) throw new CommandError(400, "Choose available export resources");
  for (const [name, model, fields2] of resources) {
    if (context2.resources && !context2.resources.includes(name)) continue;
    const cursor = context2.cursors?.[name];
    if (cursor && !mongoose206.Types.ObjectId.isValid(cursor)) throw new CommandError(400, "Invalid export cursor");
    const filter2 = { patientId, organizationId, ...context2.locationIds ? { locationId: { $in: context2.locationIds } } : {}, ...cursor ? { _id: { $gt: cursor } } : {} };
    const rows = await model.find(filter2).select(fields2).sort({ _id: 1 }).limit(101).maxTimeMS(5e3).lean();
    records[name] = rows.slice(0, 100);
    nextCursors[name] = rows.length > 100 ? String(rows[99]._id) : null;
  }
  const relationship = await PatientRelationship.findOne({ patientId, organizationId }).lean();
  await AuditLog.create({
    userId: context2.actorId,
    organizationId,
    action: "DPDP_DATA_EXPORTED",
    targetId: patientId,
    targetModel: "Patient",
    category: "COMPLIANCE_DPDP",
    details: { recordCounts: Object.fromEntries(Object.entries(records).map(([key2, rows]) => [key2, rows.length])), includeClinical: context2.includeClinical }
  });
  return {
    metadata: {
      format: "EKAVYU_DPDP_EXPORT",
      organizationId,
      exportedAt: (/* @__PURE__ */ new Date()).toISOString(),
      pageSize: 100,
      nextCursors,
      truncated: Object.values(nextCursors).some(Boolean),
      scope: context2.includeClinical ? "organization_records" : "organization_administrative_records"
    },
    patientProfile: patientAdministrativeDTO({ ...patient.toObject(), phone: relationship?.contact?.phone ?? patient.phone, email: relationship?.contact?.email ?? patient.email }),
    clinicalRecords: records,
    consentLedger: (await getPatientConsents(patientId, organizationId)).purposes
  };
}

