// routes/dpdp.ts
async function dpdpRoutes(app2) {
  const patientDataRights = {
    preHandler: [
      authenticate
    ]
  };
  const complianceAdmin = {
    preHandler: [
      authenticate,
      checkAnyPermission("ADMINISTRATIVE_GOVERNANCE")
    ]
  };
  app2.get("/api/dpdp/export", patientDataRights, exportPatientData2);
  app2.post("/api/dpdp/erasure", { ...patientDataRights, schema: privacyRequestSchema, config: { rateLimit: { max: 20, timeWindow: "1 minute" } } }, requestPatientErasure2);
  app2.get("/api/dpdp/privacy-request", patientDataRights, getPatientPrivacyRequest);
  app2.put("/api/dpdp/privacy-request/review", { ...patientDataRights, schema: privacyReviewSchema }, reviewPatientPrivacyRequest);
  app2.get("/api/dpdp/consents", patientDataRights, getPatientConsents2);
  app2.get("/api/dpdp/organizations", patientDataRights, listPrivacyOrganizations);
  app2.put("/api/dpdp/consents", { ...patientDataRights, schema: consentCommandSchema, config: { rateLimit: { max: 30, timeWindow: "1 minute" } } }, updatePatientConsents2);
  app2.post("/api/dpdp/breaches", complianceAdmin, recordBreachIncident);
  app2.get("/api/dpdp/breaches", complianceAdmin, getBreachIncidents);
  app2.get("/api/dpdp/breaches/:incidentId/dpbi-dossier", complianceAdmin, generateIncidentDPBIReport);
}

